161	      final String iosPrefix = pluginYaml['iosPrefix'] as String ?? '';
162	      platforms[IOSPlugin.kConfigKey] =
163	          IOSPlugin(
164	            name: name,
165	            classPrefix: iosPrefix,
166	            pluginClass: pluginClass,
167	          );
168	    }
169	    return Plugin(
170	      name: name,
171	      path: path,
172	      platforms: platforms,
173	      dependencies: dependencies,
174	    );
