873	void _createSymlink(String targetPath, String linkPath) {
874	  final File targetFile = globals.fs.file(targetPath);
875	  if (!targetFile.existsSync()) {
876	    throwToolExit("The file $targetPath wasn't found in the local engine out directory.");
877	  }
878	  final File linkFile = globals.fs.file(linkPath);
879	  final Link symlink = linkFile.parent.childLink(linkFile.basename);
880	  try {
881	    symlink.createSync(targetPath, recursive: true);
882	  } on FileSystemException catch (exception) {
883	    throwToolExit(
884	      'Failed to create the symlink $linkPath->$targetPath: $exception'
885	    );
886	  }
887	}
